namespace BeamScheduleFormatter {
/* Truss Support design sheet (owner, 19 November 2026): STAAD support reactions in, bearing plate / anchors / gusset / 1L-2L angle checks out */
class TrussSupportForm:DesignSheetForm {
 static readonly CultureInfo Inv=CultureInfo.InvariantCulture;
 readonly TextBox reactions=new TextBox{Multiline=true,ScrollBars=ScrollBars.Both,WordWrap=false,Width=1000,Height=260,Tag="FullWidth",Font=new Font("Consolas",9),MaxLength=0};
 readonly Label loaded=new Label{Width=1000,Height=60,Tag="FullWidth",ForeColor=PowTheme.Muted};readonly DataGridView results=new DataGridView{Width=1000,Height=520,Tag="FullWidth",ReadOnly=true,AllowUserToAddRows=false,AllowUserToDeleteRows=false,RowHeadersVisible=false,AutoSizeColumnsMode=DataGridViewAutoSizeColumnsMode.Fill};
 readonly ComboBox angle;readonly DataGridView others=new DataGridView{Width=1000,Height=170,Tag="FullWidth",AllowUserToAddRows=true,AllowUserToDeleteRows=true,RowHeadersVisible=true,AutoSizeColumnsMode=DataGridViewAutoSizeColumnsMode.Fill};readonly TrussSupportSketch sketch=new TrussSupportSketch();
 public TrussSupportForm():base("Truss Support on RC | Bearing plate, anchors and 1L / 2L angle","Truss-Support"){
  var loads=Section("STAAD reactions","Paste the STAAD Support Reactions table (Post-Processing > Reactions > Support Reactions, copy with headings): node, L/C, Fx, Fy, Fz [, Mx, My, Mz]. Use the factored (LRFD) load combinations. Rows can also be typed: node, load case, Fx, Fy, Fz.");
  Choice(loads,"Vertical","Vertical axis",new[]{"Y","Z"});NumberField(loads,"Nodes","Support nodes to design (blank = all)","");
  var act=new FlowLayoutPanel{Width=1000,Height=46,Tag="FullWidth"};Action<string,Action> button=(text,action)=>{var b=new Button{Text=text,AutoSize=true,Height=32};b.Click+=(s,e)=>{try{action();}catch(Exception ex){MessageBox.Show(this,ex.Message,text);}};act.Controls.Add(b);};
  button("Paste Support Reactions table",()=>{if(!Clipboard.ContainsText())throw new Exception("Copy the STAAD Support Reactions table first.");reactions.Text=Clipboard.GetText();});
  button("Import CSV / Excel",()=>{using(var d=new OpenFileDialog{Filter="STAAD tables|*.csv;*.tsv;*.txt;*.xlsx;*.xlsm|All files|*.*"})if(d.ShowDialog(this)==DialogResult.OK){string ext=Path.GetExtension(d.FileName).ToLowerInvariant();var texts=ext==".xlsx"||ext==".xlsm"?StaadSpreadsheet.Tables(d.FileName).Values.ToList():new List<string>{File.ReadAllText(d.FileName)};Exception last=null;foreach(var t in texts){try{string u;TrussSupport.Reactions(t,out u);reactions.Text=t;return;}catch(Exception ex){last=ex;}}throw new Exception("No Support Reactions table found. "+(last==null?"":last.Message));}});
  loads.Controls.Add(act);loads.Controls.Add(reactions);Inputs.Add("Reactions",reactions);loads.Controls.Add(loaded);reactions.TextChanged+=(s,e)=>{if(!Restoring)Refresh0();};
  var plate=Section("Plate and anchors","Bearing plate centred on the RC column / beam top, a gusset along the plate length, anchors in two rows - one each side of the gusset. Cast-in anchors per NSCP 2015 Section 417, condition B (no supplementary reinforcement).");
  NumberField(plate,"PlateB","Plate width B across the gusset (mm)","250");NumberField(plate,"PlateN","Plate length N along the gusset (mm)","300");NumberField(plate,"PlateT","Plate thickness (mm)","12");NumberField(plate,"PlateFy","Plate Fy (MPa)","248");
  NumberField(plate,"SupportB","RC support width (mm)","300");NumberField(plate,"SupportN","RC support length available (mm)","400");NumberField(plate,"SupportDepth","RC support depth below the plate (mm)","400");NumberField(plate,"Fc","Concrete fc' (MPa)","21");
  Choice(plate,"BoltDia","Anchor diameter",TrussSupport.Diameters.Select(d=>"M"+d).ToArray()).SelectedIndex=1;Choice(plate,"BoltColumns","Anchors each side of the gusset",new[]{"1","2","3","4"});NumberField(plate,"BoltS2","Anchor gauge across the gusset (mm)","150");NumberField(plate,"BoltS1","Anchor pitch along the gusset (mm)","150");
  NumberField(plate,"Hef","Embedment hef (mm)","300");Choice(plate,"AnchorType","Anchor type",new[]{"Headed (nut / head)","Hooked J or L bolt"});NumberField(plate,"HookEh","Hook length eh (mm, J/L bolt)","80");NumberField(plate,"Futa","Anchor futa (MPa)","400");NumberField(plate,"Fya","Anchor fya (MPa)","250");
  Toggle(plate,"Cracked","Cracked concrete (normal assumption)",true);Toggle(plate,"Grout","Grout pad under the plate (0.8 Vsa)",true);
  var presets=new FlowLayoutPanel{Width=1000,Height=46,Tag="FullWidth"};var typical=new Button{Text="Typical detail: 300 x 250 x 16 plate, 2-20 mm L anchor bolts each side",AutoSize=true,Height=32};typical.Click+=(s,e)=>Typical();presets.Controls.Add(typical);plate.Controls.Add(presets);plate.Controls.Add(sketch);
  var member=Section("Gusset and angle","The truss end member (1L or 2L angle) is welded to the gusset with heel and toe fillet welds; the gusset is fillet welded on both sides to the plate. Enter the member force from STAAD (Beam End Forces, axial; + tension, - compression) or leave it blank to use the support reaction.");
  NumberField(member,"GussetT","Gusset thickness tg (mm)","10");NumberField(member,"GussetL","Gusset length Lg (mm)","250");NumberField(member,"GussetH","Gusset height (mm, drawing only)","250");NumberField(member,"GussetFy","Gusset Fy (MPa)","248");NumberField(member,"GussetFu","Gusset Fu (MPa)","400");NumberField(member,"PlateWeld","Gusset-to-plate fillet weld (mm)","6");NumberField(member,"Lc","Gusset free length for buckling Lc (mm)","150");Toggle(member,"Bearing","Compression transferred by bearing",true);
  Choice(member,"Angles","Angle member",new[]{"2L (back to back)","1L"});angle=Choice(member,"Angle","Angle section (Regan handbook)",SteelCatalog.Profiles.Where(p=>p.Kind=="Angle bar").Select(p=>p.Name).ToArray());NumberField(member,"MemberForce","Member force from STAAD (kN, blank = reaction)","");
  NumberField(member,"HeelWeld","Heel weld length per angle (mm)","100");NumberField(member,"ToeWeld","Toe weld length per angle (mm)","60");NumberField(member,"AngleWeld","Angle fillet weld size (mm)","6");NumberField(member,"Fexx","Electrode FEXX (MPa, E70 = 482)","482");NumberField(member,"AngleFy","Angle Fy (MPa)","248");NumberField(member,"AngleFu","Angle Fu (MPa)","400");
  member.Controls.Add(new Label{Text="OTHER MEMBERS AT THE JOINT (bottom chord, vertical post, diagonal) - STAAD axial force, + tension / - compression",Width=1000,Height=30,Tag="FullWidth",Font=ModernUi.Strong,ForeColor=PowTheme.Teal,Padding=new Padding(0,8,0,0)});
  others.Columns.Add("Name","MEMBER");var count=new DataGridViewComboBoxColumn{Name="Angles",HeaderText="ANGLES",FlatStyle=FlatStyle.Flat};count.Items.AddRange("2L","1L");others.Columns.Add(count);var section=new DataGridViewComboBoxColumn{Name="Section",HeaderText="ANGLE SECTION",FlatStyle=FlatStyle.Flat,FillWeight=170};foreach(var p in SteelCatalog.Profiles.Where(p=>p.Kind=="Angle bar"))section.Items.Add(p.Name);others.Columns.Add(section);
  foreach(var c in new[]{new[]{"Force","FORCE (kN)"},new[]{"Heel","HEEL WELD (mm)"},new[]{"Toe","TOE WELD (mm)"},new[]{"Weld","WELD SIZE (mm)"}})others.Columns.Add(c[0],c[1]);others.DefaultValuesNeeded+=(s,e)=>{e.Row.Cells["Name"].Value="Diagonal";e.Row.Cells["Angles"].Value="2L";e.Row.Cells["Section"].Value=angle.Text;e.Row.Cells["Heel"].Value="100";e.Row.Cells["Toe"].Value="60";e.Row.Cells["Weld"].Value="6";};
  others.CellValueChanged+=(s,e)=>{if(!Restoring)Refresh0();};others.RowsRemoved+=(s,e)=>{if(!Restoring)Refresh0();};others.DataError+=(s,e)=>{e.ThrowException=false;};others.CurrentCellDirtyStateChanged+=(s,e)=>{if(others.IsCurrentCellDirty&&others.CurrentCell is DataGridViewComboBoxCell)others.CommitEdit(DataGridViewDataErrorContexts.Commit);};member.Controls.Add(others);
  var page=new TabPage("Results");foreach(var h in new[]{"CHECK","NSCP / AISC","GOVERNING NODE","LOAD CASE","DEMAND","CAPACITY","RATIO","RESULT"})results.Columns.Add("c"+results.Columns.Count,h);results.Dock=DockStyle.Fill;page.Controls.Add(results);AddResultPage(page);
  foreach(var c in Inputs.Values){c.TextChanged+=(s,e)=>{if(!Restoring)Refresh0();};var combo=c as ComboBox;if(combo!=null)combo.SelectedIndexChanged+=(s,e)=>{if(!Restoring)Refresh0();};var box=c as CheckBox;if(box!=null)box.CheckedChanged+=(s,e)=>{if(!Restoring)Refresh0();};}
  Shown+=(s,e)=>Refresh0();}
 protected override bool OptionalSavedInput(string key){return key=="Nodes"||key=="MemberForce"||key=="GussetH";}
 /* Detail 6 of the owner's drawing: 250 x 300 x 16 base plate (250 along the truss), 2-20 mm x 300 mm long L anchor bolts each side
    of the truss at 50 mm from the plate edges and 90 mm apart, 6 mm gusset 320 x 250 */
 void Typical(){var values=new Dictionary<string,string>{{"PlateN","250"},{"PlateB","300"},{"PlateT","16"},{"SupportB","300"},{"SupportN","300"},{"BoltS2","200"},{"BoltS1","90"},{"Hef","240"},{"HookEh","80"},{"GussetT","6"},{"GussetL","320"},{"GussetH","250"}};Restoring=true;try{foreach(var v in values)Inputs[v.Key].Text=v.Value;((ComboBox)Inputs["BoltDia"]).SelectedItem="M20";((ComboBox)Inputs["BoltColumns"]).SelectedItem="2";((ComboBox)Inputs["AnchorType"]).SelectedIndex=1;}finally{Restoring=false;}Refresh0();}
 protected override void WriteAdditionalState(System.Xml.XmlElement root){foreach(DataGridViewRow r in others.Rows){if(r.IsNewRow)continue;var e=root.OwnerDocument.CreateElement("JointMember");foreach(DataGridViewColumn c in others.Columns)e.SetAttribute(c.Name.ToLowerInvariant(),Convert.ToString(r.Cells[c.Index].Value,Inv));root.AppendChild(e);}}
 protected override void ReadAdditionalState(System.Xml.XmlElement root){others.Rows.Clear();foreach(System.Xml.XmlElement e in root.SelectNodes("JointMember")){int i=others.Rows.Add();foreach(DataGridViewColumn c in others.Columns){string v=e.GetAttribute(c.Name.ToLowerInvariant());var combo=c as DataGridViewComboBoxColumn;if(combo!=null&&!combo.Items.Contains(v))continue;others.Rows[i].Cells[c.Index].Value=v;}}}
 List<JointMember> OtherMembers(){var list=new List<JointMember>();foreach(DataGridViewRow r in others.Rows){if(r.IsNewRow)continue;Func<string,string> cell=n=>Convert.ToString(r.Cells[n].Value,Inv).Trim();if(cell("Section")==""&&cell("Force")=="")continue;Func<string,double> num=n=>{double v;if(!double.TryParse(cell(n),NumberStyles.Float,Inv,out v))throw new Exception("Other members row "+(r.Index+1)+": enter "+others.Columns[n].HeaderText.ToLowerInvariant()+" as a number.");return v;};
   list.Add(new JointMember{Name=cell("Name")==""?"Member "+(r.Index+2):cell("Name"),Angles=cell("Angles")=="1L"?1:2,Angle=SteelCatalog.Find(cell("Section")),Force=num("Force"),HeelWeld=num("Heel"),ToeWeld=num("Toe"),Weld=num("Weld")});}return list;}
 internal List<SupportReaction> Rows(out string unit){var all=TrussSupport.Reactions(reactions.Text,out unit);var wanted=Value("Nodes").Split(new[]{',',' ',';'},StringSplitOptions.RemoveEmptyEntries).ToList();if(wanted.Count==0)return all;var list=all.Where(r=>wanted.Contains(r.Node.Split(' ')[0])).ToList();if(list.Count==0)throw new Exception("None of the nodes "+string.Join(", ",wanted)+" is in the reactions.");return list;}
 internal TrussSupportInput Input(){Func<string,double> n=Number;string force=Value("MemberForce");return new TrussSupportInput{PlateB=n("PlateB"),PlateN=n("PlateN"),PlateT=n("PlateT"),PlateFy=n("PlateFy"),Fc=n("Fc"),SupportB=n("SupportB"),SupportN=n("SupportN"),SupportDepth=n("SupportDepth"),BoltDia=int.Parse(Value("BoltDia").Substring(1),Inv),BoltColumns=int.Parse(Value("BoltColumns"),Inv),BoltS1=n("BoltS1"),BoltS2=n("BoltS2"),Hef=n("Hef"),Futa=n("Futa"),Fya=n("Fya"),HookEh=n("HookEh"),Headed=Value("AnchorType").StartsWith("Headed"),Cracked=((CheckBox)Inputs["Cracked"]).Checked,GroutPad=((CheckBox)Inputs["Grout"]).Checked,
  GussetT=n("GussetT"),GussetL=n("GussetL"),GussetFy=n("GussetFy"),GussetFu=n("GussetFu"),PlateWeld=n("PlateWeld"),Fexx=n("Fexx"),Lc=n("Lc"),BearingCompression=((CheckBox)Inputs["Bearing"]).Checked,Angle=SteelCatalog.Find(Value("Angle")),Angles=Value("Angles").StartsWith("2L")?2:1,MemberForce=force==""?double.NaN:n("MemberForce"),HeelWeld=n("HeelWeld"),ToeWeld=n("ToeWeld"),AngleWeld=n("AngleWeld"),AngleFy=n("AngleFy"),AngleFu=n("AngleFu"),Vertical=Value("Vertical"),Others=OtherMembers()};}
 List<SupportCheck> lastChecks;List<string> lastNotes;
 void Refresh0(){try{double gh;sketch.Show(Input(),double.TryParse(Value("GussetH"),NumberStyles.Float,Inv,out gh)?gh:250);}catch(Exception){sketch.Show(null,0);}results.Rows.Clear();if(reactions.Text.Trim()==""){loaded.Text="No reactions yet. Paste or import the STAAD Support Reactions table.";return;}
  try{string unit;var rows=Rows(out unit);loaded.ForeColor=PowTheme.Muted;loaded.Text=rows.Count+" reaction rows, "+rows.Select(r=>r.Node).Distinct().Count()+" node(s), "+rows.Select(r=>r.Case).Distinct().Count()+" load case(s); unit "+unit+". Largest downward "+TrussSupport.F(rows.Max(r=>Value("Vertical")=="Z"?r.Fz:r.Fy))+" kN, largest uplift "+TrussSupport.F(Math.Max(0,-rows.Min(r=>Value("Vertical")=="Z"?r.Fz:r.Fy)))+" kN.";
   var notes=new List<string>();var checks=TrussSupport.Check(Input(),rows,notes);lastChecks=checks;lastNotes=notes;
   foreach(var c in checks){int i=results.Rows.Add(c.Name,c.Clause,c.Node,c.Case,TrussSupport.F(c.Demand,"0.00")+" "+c.Unit,TrussSupport.F(c.Capacity,"0.00")+" "+c.Unit,TrussSupport.F(c.Ratio,"0.00"),c.Ok?"OK":"NG");if(!c.Ok)results.Rows[i].DefaultCellStyle.ForeColor=Color.Firebrick;}
   int ng=checks.Count(c=>!c.Ok);loaded.ForeColor=ng>0?Color.Firebrick:PowTheme.Teal;loaded.Text+="\r\n"+(ng>0?ng+" check(s) NG - see Results.":"All checks pass - largest ratio "+TrussSupport.F(checks.Max(c=>c.Ratio),"0.00")+".");}
  catch(Exception ex){lastChecks=null;loaded.ForeColor=Color.Firebrick;loaded.Text=ex.Message;}}
 protected override void AfterRestore(){Refresh0();}
 protected override string BuildReport(){string unit;var rows=Rows(out unit);var input=Input();var notes=new List<string>();var checks=TrussSupport.Check(input,rows,notes);var b=new StringBuilder();
  b.AppendLine("TRUSS SUPPORT ON RC COLUMN / BEAM - BEARING PLATE, ANCHORS AND "+(input.Angles==2?"2L":"1L")+" ANGLE");b.AppendLine();
  b.AppendLine("## 01  DESIGN BASIS");b.AppendLine("LRFD, NSCP 2015: Section 417 (anchoring to concrete, ACI 318-14 Ch. 17), Section 510.8 (bearing), Chapter 5 / AISC 360-10 (steel, welds). STAAD factored support reactions, unit "+unit+"; vertical axis "+input.Vertical+" (positive = downward load on the support).");b.AppendLine();
  b.AppendLine("## 02  INPUTS");b.AppendLine("Plate "+TrussSupport.F(input.PlateB,"0")+" x "+TrussSupport.F(input.PlateN,"0")+" x "+TrussSupport.F(input.PlateT,"0")+" mm, Fy "+TrussSupport.F(input.PlateFy,"0")+" MPa; RC support "+TrussSupport.F(input.SupportB,"0")+" x "+TrussSupport.F(input.SupportN,"0")+" mm, depth "+TrussSupport.F(input.SupportDepth,"0")+" mm, fc' "+TrussSupport.F(input.Fc,"0.#")+" MPa.");
  b.AppendLine("Gusset "+TrussSupport.F(input.GussetT,"0")+" x "+TrussSupport.F(input.GussetL,"0")+" mm (Fy "+TrussSupport.F(input.GussetFy,"0")+", Fu "+TrussSupport.F(input.GussetFu,"0")+" MPa), "+TrussSupport.F(input.PlateWeld,"0")+" mm fillet both sides; angle "+(input.Angles==2?"2L ":"1L ")+input.Angle.Name+", heel / toe welds "+TrussSupport.F(input.HeelWeld,"0")+" / "+TrussSupport.F(input.ToeWeld,"0")+" mm x "+TrussSupport.F(input.AngleWeld,"0")+" mm, FEXX "+TrussSupport.F(input.Fexx,"0")+" MPa.");
  foreach(var n in notes)b.AppendLine(n);b.AppendLine();
  b.AppendLine("## 03  STAAD SUPPORT REACTIONS (kN)");b.AppendLine("Node      L/C                     Fx         Fy         Fz");foreach(var r in rows.Take(60))b.AppendLine(r.Node.PadRight(10)+(r.Case.Length>22?r.Case.Substring(0,22):r.Case).PadRight(24)+TrussSupport.F(r.Fx,"0.00").PadLeft(9)+TrussSupport.F(r.Fy,"0.00").PadLeft(11)+TrussSupport.F(r.Fz,"0.00").PadLeft(11));if(rows.Count>60)b.AppendLine("... "+(rows.Count-60)+" more rows checked.");b.AppendLine();
  b.AppendLine("## 04  CHECKS (governing reaction row for each)");b.AppendLine("Check                          Clause          Node    L/C           Demand        Capacity      Ratio  Result");foreach(var c in checks)b.AppendLine(c.Name.PadRight(31)+c.Clause.PadRight(16)+c.Node.PadRight(8)+(c.Case.Length>12?c.Case.Substring(0,12):c.Case).PadRight(14)+(TrussSupport.F(c.Demand,"0.00")+" "+c.Unit).PadRight(14)+(TrussSupport.F(c.Capacity,"0.00")+" "+c.Unit).PadRight(14)+TrussSupport.F(c.Ratio,"0.00").PadRight(7)+(c.Ok?"OK":"NG")+"   "+c.Note);
  b.AppendLine();int ng=checks.Count(c=>!c.Ok);b.AppendLine(ng==0?"All checks satisfied for the reactions given.":ng+" check(s) not satisfied - revise the plate, anchors, gusset or welds.");b.AppendLine("Design calculation prepared with DTCE Tool Kit; it is not an engineer's approval. Confirm the support detail, anchor layout and reinforcement around the anchors on the structural drawings.");
  return b.ToString();}
}
}

namespace BeamScheduleFormatter {
/* plan and elevation of the support, drawn from the inputs */
class TrussSupportSketch:Control {
 TrussSupportInput input;double gussetH;static readonly CultureInfo Inv=CultureInfo.InvariantCulture;
 public TrussSupportSketch(){DoubleBuffered=true;ResizeRedraw=true;Width=1000;Height=380;Tag="FullWidth";BackColor=Color.White;}
 public void Show(TrussSupportInput i,double h){input=i;gussetH=h;Invalidate();}
 static string F(double v){return v.ToString("0",Inv);}
 void Dim(Graphics g,Font f,Brush b,Pen p,PointF a,PointF c,string text,bool vertical){g.DrawLine(p,a,c);if(vertical){g.DrawLine(p,a.X-3,a.Y,a.X+3,a.Y);g.DrawLine(p,c.X-3,c.Y,c.X+3,c.Y);var size=g.MeasureString(text,f);g.DrawString(text,f,b,a.X-size.Width-4,(a.Y+c.Y)/2-size.Height/2);}else{g.DrawLine(p,a.X,a.Y-3,a.X,a.Y+3);g.DrawLine(p,c.X,c.Y-3,c.X,c.Y+3);var size=g.MeasureString(text,f);g.DrawString(text,f,b,(a.X+c.X)/2-size.Width/2,a.Y-size.Height-1);}}
 protected override void OnPaint(PaintEventArgs e){base.OnPaint(e);var g=e.Graphics;g.SmoothingMode=SmoothingMode.AntiAlias;var font=new Font("Segoe UI",8f);var bold=ModernUi.Strong;
  using(var ink=new SolidBrush(PowTheme.Ink))using(var muted=new SolidBrush(PowTheme.Muted))using(var line=new Pen(PowTheme.Ink,1.3f))using(var dim=new Pen(PowTheme.Muted)){
   if(input==null){g.DrawString("Enter the plate, anchor and gusset sizes to see the detail.",font,muted,12,12);return;}var i=input;
   float half=Width/2f;g.DrawString("PLAN",bold,ink,12,8);g.DrawString("ELEVATION",bold,ink,half+12,8);
   /* plan: N along the truss (horizontal), B across */
   double spanX=Math.Max(i.SupportN,Math.Max(i.PlateN,i.GussetL))+120,spanY=Math.Max(i.SupportB,i.PlateB)+120;float k=(float)Math.Min((half-60)/spanX,(Height-80)/spanY);float cx=half/2,cy=Height/2f+10;
   Func<double,float> X=x=>cx+(float)(x*k);Func<double,float> Y=y=>cy+(float)(y*k);
   using(var dash=new Pen(Color.Gray){DashStyle=DashStyle.Dash})g.DrawRectangle(dash,X(-i.SupportN/2),Y(-i.SupportB/2),(float)(i.SupportN*k),(float)(i.SupportB*k));
   using(var plate=new SolidBrush(Color.FromArgb(225,232,240)))g.FillRectangle(plate,X(-i.PlateN/2),Y(-i.PlateB/2),(float)(i.PlateN*k),(float)(i.PlateB*k));g.DrawRectangle(line,X(-i.PlateN/2),Y(-i.PlateB/2),(float)(i.PlateN*k),(float)(i.PlateB*k));
   using(var gus=new SolidBrush(Color.FromArgb(90,110,140)))g.FillRectangle(gus,X(-i.GussetL/2),Y(-i.GussetT/2)-1,(float)(i.GussetL*k),Math.Max(3,(float)(i.GussetT*k)));
   double run=(i.BoltColumns-1)*i.BoltS1;using(var bolt=new SolidBrush(Color.Black))for(int c=0;c<i.BoltColumns;c++)foreach(int side in new[]{-1,1}){double x=-run/2+c*i.BoltS1,y=side*i.BoltS2/2;float r=Math.Max(3,(float)(i.BoltDia*k/2));g.FillEllipse(bolt,X(x)-r,Y(y)-r,2*r,2*r);}
   Dim(g,font,muted,dim,new PointF(X(-i.PlateN/2),Y(-i.PlateB/2)-18),new PointF(X(i.PlateN/2),Y(-i.PlateB/2)-18),F(i.PlateN),false);Dim(g,font,muted,dim,new PointF(Math.Min(X(-i.PlateN/2),X(-i.SupportN/2))-20,Y(-i.PlateB/2)),new PointF(Math.Min(X(-i.PlateN/2),X(-i.SupportN/2))-20,Y(i.PlateB/2)),F(i.PlateB),true);
   double edge=(i.PlateB-i.BoltS2)/2;float left=Math.Min(X(-i.PlateN/2),X(-i.SupportN/2))-58;Dim(g,font,muted,dim,new PointF(left,Y(-i.PlateB/2)),new PointF(left,Y(-i.BoltS2/2)),F(edge),true);Dim(g,font,muted,dim,new PointF(left,Y(-i.BoltS2/2)),new PointF(left,Y(i.BoltS2/2)),F(i.BoltS2),true);
   if(i.BoltColumns>1)Dim(g,font,muted,dim,new PointF(X(-run/2),Y(i.PlateB/2)+18),new PointF(X(run/2),Y(i.PlateB/2)+18),F(i.BoltS1),false);
   g.DrawString(F(i.PlateN)+" x "+F(i.PlateB)+" x "+F(i.PlateT)+" mm plate, "+(2*i.BoltColumns)+" - "+i.BoltDia+" mm "+(i.Headed?"headed":"L")+" anchors ("+i.BoltColumns+" each side)",font,ink,12,Height-22);
   /* elevation: along the truss */
   double ew=Math.Max(i.SupportN,i.GussetL)+160,eh=gussetH+i.PlateT+i.Hef+140;float ke=(float)Math.Min((half-60)/ew,(Height-70)/eh);float ex=half+half/2,ey=30+(float)(gussetH*ke)+20;
   Func<double,float> EX=x=>ex+(float)(x*ke);Func<double,float> EY=y=>ey+(float)(y*ke);
   using(var conc=new HatchBrush(HatchStyle.Percent10,Color.Gray,Color.FromArgb(240,240,236)))g.FillRectangle(conc,EX(-i.SupportN/2),EY(i.PlateT),(float)(i.SupportN*ke),(float)((i.Hef+80)*ke));g.DrawRectangle(dim,EX(-i.SupportN/2),EY(i.PlateT),(float)(i.SupportN*ke),(float)((i.Hef+80)*ke));
